const learningPatch="const optics=(window.MAOptique?.card(window.MASimple?.scopeFor(st.screen),tab,query)||'')+(window.MAPrixPsychologique?.card(window.MASimple?.scopeFor(st.screen),tab,query)||'')+(window.MAGFCh1?.card(window.MASimple?.scopeFor(st.screen),tab,query)||'');";
